def unique(l: list) -> List[Any]:
    """Return sorted unique elements in a list.
    If elements cannot be hashed or cannot be compared for sorting, the function
    falls back to preserving the original order of first occurrences and returns
    that deduplicated list (unsorted if sorting is not possible).
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    # Try the fast path: use a set to deduplicate, then sort.
    try:
        uniq_set = set(l)
        try:
            return sorted(uniq_set)
        except TypeError:
            # Sorting failed (likely due to incomparable types).
            # Build deduplicated list preserving original order using a seen set.
            deduped = []
            seen = set()
            for x in l:
                if x not in seen:
                    seen.add(x)
                    deduped.append(x)
            try:
                return sorted(deduped)
            except TypeError:
                return deduped
    except TypeError:
        # Elements are unhashable (e.g., lists). Deduplicate preserving order.
        deduped = []
        for x in l:
            # membership test against deduped list (O(n) per check)
            if x not in deduped:
                deduped.append(x)
        try:
            return sorted(deduped)
        except TypeError:
            return deduped

