def sort_array(array):
    """
    Given an array of non-negative integers, return a copy of the given array after sorting.
    Sort in ascending order if the sum (first element + last element) is odd,
    or in descending order if that sum is even.

    The given array should not be modified; a new list is returned.
    """
    # Handle empty sequence
    if not array:
        return []
    # Make a list copy so the original is not modified
    arr = list(array)
    # If sum of first and last is odd -> ascending, else descending
