        return sorted(arr)
    else:
        return sorted(arr, reverse=True)

def encrypt(s):
    """Create a function encrypt that takes a string as an argument and
    returns a string encrypted with the alphabet being rotated by 4 places.
    Non-alphabet characters are left unchanged. Case is preserved.
    """
    result_chars = []
    shift = 4
    for c in s:
        if 'a' <= c <= 'z':
            # shift within lowercase
            new_ord = (ord(c) - ord('a') + shift) % 26 + ord('a')
            result_chars.append(chr(new_ord))
        elif 'A' <= c <= 'Z':
            # shift within uppercase
            new_ord = (ord(c) - ord('A') + shift) % 26 + ord('A')
            result_chars.append(chr(new_ord))
        else:
            # leave other characters unchanged
            result_chars.append(c)
    return ''.join(result_chars)

import re

def is_bored(S):
    """
    You'll be given a string of words, and your task is to count the number
    of boredoms. A boredom is a sentence that starts with the word "I".
    Sentences are delimited by '.', '?' or '!'.
    """
    count = 0
    start = 0
    delimiters = {'.', '?', '!'}
    # iterate through the string and split on sentence delimiters
    for i, ch in enumerate(S):
        if ch in delimiters:
            sentence = S[start:i].strip()
            if sentence:
                # allow optional leading non-alphanumeric chars (e.g. quotes) before checking for 'I' as a whole word
                if re.match(r'^[^A-Za-z0-9]*I\b', sentence):
                    count += 1
            start = i + 1
    # process final trailing segment (if any)
    final_sentence = S[start:].strip()
    if final_sentence:
        if re.match(r'^[^A-Za-z0-9]*I\b', final_sentence):
            count += 1
    return count

