def count_up_to(n):
    # Return a list of all prime numbers strictly less than n.
    if not isinstance(n, int) or n < 2:
        return []
    sieve = [True] * n
    sieve[0] = False
    sieve[1] = False

    limit = int(n ** 0.5)
    for p in range(2, limit + 1):
        if sieve[p]:
            start = p * p
            for multiple in range(start, n, p):
                sieve[multiple] = False

    return [i for i, is_prime in enumerate(sieve) if is_prime]

def rounded_avg(n, m):
    """You are given two positive integers n and m, and your task is to compute the
    average of the integers from n through m (including n and m). 
    Round the answer to the nearest integer and convert that to binary.
    If n is greater than m, return -1.
    """
    # Validate input ordering
    if n > m:
        return -1

    s = n + m
    q = s // 2
    r = s % 2

    if r == 0:
        avg_rounded = q
    else:
        # s is odd -> actual average is q + 0.5
        # tie-to-even: if q is even, round to q; otherwise round to q+1
        if q % 2 == 0:
            avg_rounded = q
        else:
            avg_rounded = q + 1

    return bin(avg_rounded)

