    return count

from collections import Counter

def histogram(test):
    """Given a string representing space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    # Handle empty or whitespace-only input
    if not test or test.strip() == '':
        return {}

    # Split on any whitespace to get the letters
    parts = test.split()

    # Count occurrences
    counts = Counter(parts)

    # Find maximum occurrence
    max_count = max(counts.values())

    # Build result dict with letters that have the max count
    result = {letter: cnt for letter, cnt in counts.items() if cnt == max_count}
    return result

